-- Paket ABT "abt-butir-rata-31okt": PRASYARAT "A|B": A = fungsi isian_rtf_butir dan isian_rtf_judul yang persis LAMA (2 pasang pertama) | B = persis BARU (2 pasang ulang).
SELECT CONCAT((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND ((routine_name = 'isian_rtf_butir' AND MD5(routine_definition) = '09d18b43578793de666e87940ab25803') OR (routine_name = 'isian_rtf_judul' AND MD5(routine_definition) = '101c5388520cd5ffa56535a3b31c5747'))), '|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema = DATABASE() AND ((routine_name = 'isian_rtf_butir' AND MD5(routine_definition) = '697b3e7bab7a2735d3e252424797b1f3') OR (routine_name = 'isian_rtf_judul' AND MD5(routine_definition) = '2ea51f44c572718acc9ad233fcc1c7f6')))) AS p;
